begin;
create function pg_temp.assert_true(ok boolean,label text) returns void language plpgsql as $$begin if ok is distinct from true then raise exception 'FAIL: %',label;end if;end $$;
insert into auth.users(id,email) values('00000000-0000-4000-8000-00000000da01','operations-owner@example.invalid'),('00000000-0000-4000-8000-00000000db01','operations-agent@example.invalid');
select set_config('request.jwt.claims','{"sub":"00000000-0000-4000-8000-00000000da01","role":"authenticated","aal":"aal2"}',true);
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"00000000-0000-4000-8000-00000000da01","role":"authenticated","aal":"aal2"}',true);
insert into public.atraction_tenants(id,name,owner_id,capture_slug,capture_enabled) values('00000000-0000-4000-8000-00000000da02','Operations test','00000000-0000-4000-8000-00000000da01','operations-fixture',true);
insert into public.atraction_contacts(id,tenant_id,owner_id,name,phone) values('00000000-0000-4000-8000-00000000da03','00000000-0000-4000-8000-00000000da02','00000000-0000-4000-8000-00000000da01','Source','+5521998888777'),('00000000-0000-4000-8000-00000000da04','00000000-0000-4000-8000-00000000da02','00000000-0000-4000-8000-00000000da01','Target','+5521998888778');
insert into public.atraction_accounts(id,tenant_id,name,kind,initial_date) values('00000000-0000-4000-8000-00000000da05','00000000-0000-4000-8000-00000000da02','Bank','bank',current_date);
insert into public.atraction_finance(id,tenant_id,title,direction,amount_cents,category,due_date,contact_id) values('00000000-0000-4000-8000-00000000da06','00000000-0000-4000-8000-00000000da02','Partial','income',10000,'Services',current_date,'00000000-0000-4000-8000-00000000da03');
select public.atraction_record_payment('00000000-0000-4000-8000-00000000da06',3000,current_date,'00000000-0000-4000-8000-00000000da05','00000000-0000-4000-8000-00000000da07');
select public.atraction_record_payment('00000000-0000-4000-8000-00000000da06',3000,current_date,'00000000-0000-4000-8000-00000000da05','00000000-0000-4000-8000-00000000da07');
select pg_temp.assert_true((select jsonb_array_length(payments)=1 and settled_date is null from public.atraction_finance where id='00000000-0000-4000-8000-00000000da06'),'partial and idempotent');
do $$begin begin perform public.atraction_record_payment('00000000-0000-4000-8000-00000000da06',8000,current_date,null,gen_random_uuid());raise exception 'FAIL: overpaid';exception when raise_exception then if sqlerrm like 'FAIL:%' then raise;end if;end;end $$;
do $$begin begin update public.atraction_finance set payments='[]';raise exception 'FAIL: bypass';exception when raise_exception then if sqlerrm like 'FAIL:%' then raise;end if;end;end $$;
select public.atraction_record_payment('00000000-0000-4000-8000-00000000da06',7000,current_date,null,gen_random_uuid());
select pg_temp.assert_true((select settled_date=current_date from public.atraction_finance where id='00000000-0000-4000-8000-00000000da06'),'full paid');
select public.atraction_record_payment('00000000-0000-4000-8000-00000000da06',0,current_date,null,gen_random_uuid(),'00000000-0000-4000-8000-00000000da07');
select pg_temp.assert_true((select settled_date is null and jsonb_array_length(payments)=1 from public.atraction_finance where id='00000000-0000-4000-8000-00000000da06'),'reverse partial');
do $$begin begin update public.atraction_contacts set merged_into=id where id='00000000-0000-4000-8000-00000000da03';raise exception 'FAIL: merge pointer bypass';exception when raise_exception then if sqlerrm like 'FAIL:%' then raise;end if;end;end $$;
select public.atraction_merge_contacts('00000000-0000-4000-8000-00000000da03','00000000-0000-4000-8000-00000000da04');
select pg_temp.assert_true((select contact_id='00000000-0000-4000-8000-00000000da04' from public.atraction_finance where id='00000000-0000-4000-8000-00000000da06'),'merge financial links');
do $$begin begin update public.atraction_contacts set deleted_at=null where id='00000000-0000-4000-8000-00000000da03';raise exception 'FAIL: restore merged';exception when raise_exception then if sqlerrm like 'FAIL:%' then raise;end if;end;end $$;
reset role;
insert into public.atraction_members(tenant_id,user_id,role) values('00000000-0000-4000-8000-00000000da02','00000000-0000-4000-8000-00000000db01','agent');
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"00000000-0000-4000-8000-00000000da01","role":"authenticated","aal":"aal2"}',true);
update public.atraction_contacts set owner_id='00000000-0000-4000-8000-00000000db01' where id='00000000-0000-4000-8000-00000000da04';
select public.atraction_member_role('00000000-0000-4000-8000-00000000da02','00000000-0000-4000-8000-00000000db01','viewer');
select pg_temp.assert_true((select owner_id='00000000-0000-4000-8000-00000000da01' from public.atraction_contacts where id='00000000-0000-4000-8000-00000000da04'),'member reassignment');
set local role anon;
select set_config('request.jwt.claims','{"role":"anon"}',true);
select set_config('test.chat',public.atraction_chat_start('operations-fixture','Visitor','+5521998888777',true)::text,true);
select public.atraction_chat_send((current_setting('test.chat')::jsonb->>'id')::uuid,current_setting('test.chat')::jsonb->>'token','Hello','00000000-0000-4000-8000-00000000da08');
select public.atraction_chat_send((current_setting('test.chat')::jsonb->>'id')::uuid,current_setting('test.chat')::jsonb->>'token','Hello','00000000-0000-4000-8000-00000000da08');
select pg_temp.assert_true(jsonb_array_length(public.atraction_chat_poll((current_setting('test.chat')::jsonb->>'id')::uuid,current_setting('test.chat')::jsonb->>'token')->'messages')=1,'public visitor chat');
do $$begin begin perform public.atraction_chat_poll((current_setting('test.chat')::jsonb->>'id')::uuid,'wrong-token');raise exception 'FAIL: token isolation';exception when raise_exception then if sqlerrm like 'FAIL:%' then raise;end if;end;end $$;
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"00000000-0000-4000-8000-00000000da01","role":"authenticated","aal":"aal2"}',true);
insert into public.atraction_chat_messages(tenant_id,session_id,body,direction,client_id) values('00000000-0000-4000-8000-00000000da02',(current_setting('test.chat')::jsonb->>'id')::uuid,'Welcome','out',gen_random_uuid());
select pg_temp.assert_true((select contact_id='00000000-0000-4000-8000-00000000da04' from public.atraction_chat_sessions where id=(current_setting('test.chat')::jsonb->>'id')::uuid),'merged phone routes to target');
set local role anon;
select set_config('request.jwt.claims','{"role":"anon"}',true);
select pg_temp.assert_true(jsonb_array_length(public.atraction_chat_poll((current_setting('test.chat')::jsonb->>'id')::uuid,current_setting('test.chat')::jsonb->>'token')->'messages')=2,'visitor receives reply');
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"00000000-0000-4000-8000-00000000da01","role":"authenticated","aal":"aal2"}',true);
update public.atraction_chat_sessions set closed=true;
set local role anon;
select set_config('request.jwt.claims','{"role":"anon"}',true);
do $$begin begin perform public.atraction_chat_send((current_setting('test.chat')::jsonb->>'id')::uuid,current_setting('test.chat')::jsonb->>'token','Closed',gen_random_uuid());raise exception 'FAIL: closed sends';exception when raise_exception then if sqlerrm like 'FAIL:%' then raise;end if;end;end $$;
select 'operations security passed' as result;
